  String(text ?? '').split('\n').forEach(l => {
    const m = /^([a-z][a-z0-9_]*)=(.*)$/i.exec(l.trim());
    if (m) (kv[m[1]] = kv[m[1]] || []).push(m[2]); else if (l.trim()) other.push(l.trim());
  });
